import { getMethodOpts } from '../../options/method.js'
import { finalizePluginsOpts } from '../../options/plugins.js'
import { classesData } from '../../subclass/map.js'
import { getPluginInfo } from '../info/main.js'

// Called on `ErrorClass[methodName](...args)`
export const callStaticMethod = (
  { methodFunc, plugin, plugins, ErrorClass },
  ...args
) => {
  const { classOpts } = classesData.get(ErrorClass)
  const { args: argsA, methodOpts } = getMethodOpts(args, plugin)
  const options = finalizePluginsOpts({
    pluginsOpts: classOpts,
    methodOpts,
    plugins,
    plugin,
  })
  const info = getPluginInfo({
    options,
    ErrorClass,
    methodOpts,
    plugins,
    plugin,
  })
  return methodFunc(info, ...argsA)
}

src/subclass/validate.js.source:
import { classesData } from './map.js'

// We forbid subclasses that are not known, i.e. not passed to
// `ErrorClass.subclass()`
//  - They would not be validated at load time
//  - The class would not be normalized until its first instantiation
//     - E.g. its `prototype.name` might be missing
//  - The list of `ErrorClasses` would be potentially incomplete
//     - E.g. `ErrorClass.parse()` would not be able to parse an error class
//       until its first instantiation
// This usually happens if a class was:
//  - Not passed to the `custom` option of `*Error.subclass()`
//  - But was extended from a known class
export const validateSubclass = (ErrorClass) => {
  if (classesData.has(ErrorClass)) {
    return
  }

  const { name } = ErrorClass
  const { name: parentName } = Object.getPrototypeOf(ErrorClass)
  throw new Error(
    `"new ${name}()" must not be directly called.
This error class should be created like this instead:
  export const ${name} = ${parentName}.subclass('${name}')`,
  )
}

src/options/clone.js.source:
import isPlainObj from 'is-plain-obj'

// Deep clone an object except for class instances.
// This is done on:
//  - Plugins options before storing them for later usage:
//     - For class options and error instance options
//     - So that, if user mutates them, this does not change the options used
//       internally
//  - Most arguments passed to `plugin.*()` methods:
//     - This prevents mutations by plugins from impacting the logic
//     - This also allows exposing plugin methods arguments to users
//        - E.g. by returning them or setting them to `error.*`
//        - Without any risk for mutations to impact the logic
//           - E.g. shared `props` can be set and mutated on each error instance
//             without propagating to other instances
export const deepClone = (value) => {
  if (Array.isArray(value)) {
    return value.map(deepClone)
  }

  if (isPlainObj(value)) {
    return deepCloneObject(value)
  }

  return value
}

const deepCloneObject = (object) => {
  const copy = {}

  // eslint-disable-next-line fp/no-loops
  for (const key of Reflect.ownKeys(object)) {
    const descriptor = Object.getOwnPropertyDescriptor(object, key)
    const childCopy = deepClone(descriptor.value)
    // eslint-disable-next-line fp/no-mutating-methods
    Object.defineProperty(copy, key, { ...descriptor, value: childCopy })
  }

  return copy
}

