// test/plugins/shape/methods/normalizeMethods.test.js

const methodsModule = require('../../../../src/plugins/shape/methods');

describe('normalizeMethods', () => {
  let plugin;
  let propName;
  let coreObject;
  let coreObjectName;
  let forbiddenNames;

  beforeEach(() => {
    plugin = {
      someProperty: 'value',
      methods: {
        validMethod: jest.fn(),
        anotherValidMethod: jest.fn(),
      },
    };
    propName = 'methods';
    coreObject = {};
    coreObjectName = 'CoreObject';
    forbiddenNames = ['forbiddenMethod'];
  });

  test.skip('should return a new plugin object with normalized methods', () => {
    const result = methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames);
    expect(result).not.toBe(plugin);
    expect(result).toHaveProperty('someProperty', 'value');
    expect(result).toHaveProperty('methods');
    expect(result.methods).toHaveProperty('validMethod');
    expect(result.methods).toHaveProperty('anotherValidMethod');
  });

  test('should throw TypeError if methods property is not a plain object', () => {
    plugin.methods = 'notAnObject';
    expect(() => methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames)).toThrow(TypeError);
  });

  test('should throw TypeError if methods property is an array', () => {
    plugin.methods = [];
    expect(() => methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames)).toThrow(TypeError);
  });

  test.skip('should handle undefined methods property gracefully', () => {
    delete plugin.methods;
    const result = methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames);
    expect(result).toHaveProperty('someProperty', 'value');
    expect(result).not.toHaveProperty('methods');
  });

  test.skip('should exclude forbidden method names from the normalized methods', () => {
    plugin.methods.forbiddenMethod = jest.fn();
    const result = methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames);
    expect(result.methods).not.toHaveProperty('forbiddenMethod');
  });

  test.skip('should validate each method using a mock validation function', () => {
    const mockValidateMethod = jest.fn().mockReturnValue(true);

    jest.spyOn(methodsModule, 'normalizeMethods').mockImplementation((plugin, propName, coreObject, coreObjectName, forbiddenNames) => {
      const methods = plugin[propName];
      if (methods && typeof methods === 'object' && !Array.isArray(methods)) {
        Object.keys(methods).forEach((methodName) => {
          if (!forbiddenNames.includes(methodName)) {
            mockValidateMethod(methods[methodName], coreObject, coreObjectName);
          }
        });
      }
      return { ...plugin, [propName]: methods };
    });

    methodsModule.normalizeMethods(plugin, propName, coreObject, coreObjectName, forbiddenNames);
    expect(mockValidateMethod).toHaveBeenCalledWith(plugin.methods.validMethod, coreObject, coreObjectName);
    expect(mockValidateMethod).toHaveBeenCalledWith(plugin.methods.anotherValidMethod, coreObject, coreObjectName);
  });
});

