// test/plugins/shape/methods/normalizeAllMethods.test.js
const { normalizeAllMethods } = require('../../../../src/plugins/shape/methods');

describe('normalizeAllMethods', () => {
  let INSTANCE_METHODS;
  let STATIC_METHODS;
  let mockPlugin;

  beforeEach(() => {
    INSTANCE_METHODS = ['instanceMethod1', 'instanceMethod2'];
    STATIC_METHODS = ['staticMethod1', 'staticMethod2'];

    mockPlugin = {
      instanceMethod1: jest.fn(),
      instanceMethod2: jest.fn(),
      staticMethod1: jest.fn(),
      staticMethod2: jest.fn(),
    };
  });

  it('should return a new object', () => {
    const result = normalizeAllMethods(mockPlugin);
    expect(result).not.toBe(mockPlugin);
  });

  it.skip('should throw TypeError if plugin is not an object', () => {
    expect(() => normalizeAllMethods(null)).toThrow(TypeError);
    expect(() => normalizeAllMethods(undefined)).toThrow(TypeError);
    expect(() => normalizeAllMethods(42)).toThrow(TypeError);
    expect(() => normalizeAllMethods('string')).toThrow(TypeError);
  });

  it('should normalize instance methods first', () => {
    const result = normalizeAllMethods(mockPlugin);
    INSTANCE_METHODS.forEach(method => {
      expect(result[method]).toBeDefined();
      expect(typeof result[method]).toBe('function');
    });
  });

  it('should normalize static methods using normalized instance methods', () => {
    const result = normalizeAllMethods(mockPlugin);
    STATIC_METHODS.forEach(method => {
      expect(result[method]).toBeDefined();
      expect(typeof result[method]).toBe('function');
    });
  });

  it('should not alter the original plugin object', () => {
    const originalPlugin = { ...mockPlugin };
    normalizeAllMethods(mockPlugin);
    expect(mockPlugin).toEqual(originalPlugin);
  });

  it('should handle plugins with no methods gracefully', () => {
    const emptyPlugin = {};
    const result = normalizeAllMethods(emptyPlugin);
    expect(result).toEqual({
      instanceMethods: {},
      staticMethods: {},
    });
  });

  it('should handle plugins with only instance methods', () => {
    const instanceOnlyPlugin = {
      instanceMethod1: jest.fn(),
      instanceMethod2: jest.fn(),
    };
    const result = normalizeAllMethods(instanceOnlyPlugin);
    INSTANCE_METHODS.forEach(method => {
      expect(result[method]).toBeDefined();
      expect(typeof result[method]).toBe('function');
    });
  });

  it('should handle plugins with only static methods', () => {
    const staticOnlyPlugin = {
      staticMethod1: jest.fn(),
      staticMethod2: jest.fn(),
    };
    const result = normalizeAllMethods(staticOnlyPlugin);
    STATIC_METHODS.forEach(method => {
      expect(result[method]).toBeDefined();
      expect(typeof result[method]).toBe('function');
    });
  });
});

