const validateEachPlugin = require('../../../../src/plugins/shape/duplicate.js');

class CustomError extends Error {}

describe('validateEachPlugin', () => {
  const createPlugin = (name, fullName, instanceMethods = [], staticMethods = []) => ({
    name,
    fullName,
    instanceMethods,
    staticMethods,
  });

  test.skip('should not throw an error for non-conflicting plugins', () => {
    const pluginA = createPlugin('pluginA', 'Plugin A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('pluginB', 'Plugin B', ['method2'], ['staticMethod2']);

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, CustomError);
    }).not.toThrow();
  });

  test('should throw a TypeError if plugins have the same name', () => {
    const pluginA = createPlugin('plugin', 'Plugin A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('plugin', 'Plugin B', ['method2'], ['staticMethod2']);

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, CustomError);
    }).toThrow(TypeError);
  });

  test('should throw a TypeError if plugins have duplicate instance methods', () => {
    const pluginA = createPlugin('pluginA', 'Plugin A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('pluginB', 'Plugin B', ['method1'], ['staticMethod2']);

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, CustomError);
    }).toThrow(TypeError);
  });

  test('should throw a TypeError if plugins have duplicate static methods', () => {
    const pluginA = createPlugin('pluginA', 'Plugin A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('pluginB', 'Plugin B', ['method2'], ['staticMethod1']);

    expect(() => {
      validateEachPlugin(pluginA, pluginB, 0, 1, CustomError);
    }).toThrow(TypeError);
  });

  test.skip('should not throw an error if the same plugin is compared with itself', () => {
    const pluginA = createPlugin('pluginA', 'Plugin A', ['method1'], ['staticMethod1']);

    expect(() => {
      validateEachPlugin(pluginA, pluginA, 0, 0, CustomError);
    }).not.toThrow();
  });

  test.skip('should throw a TypeError with a descriptive message', () => {
    const pluginA = createPlugin('plugin', 'Plugin A', ['method1'], ['staticMethod1']);
    const pluginB = createPlugin('plugin', 'Plugin B', ['method2'], ['staticMethod2']);

    try {
      validateEachPlugin(pluginA, pluginB, 0, 1, CustomError);
    } catch (error) {
      expect(error).toBeInstanceOf(TypeError);
      expect(error.message).toContain('plugin');
    }
  });
});

