      },
      options: {
        enabled: true,
      },
    });
  });

  it.skip('should throw a TypeError if the plugin is not a plain object', () => {
    const plugin = 'notAnObject';

    expect(() => normalizePlugin(plugin, TestError)).toThrow(TypeError);
