test/options/clone/deepClone.test.js.source:
const deepClone = require('../../../src/options/clone').deepClone;

describe('deepClone', () => {
  test('should return the same primitive value for numbers', () => {
    const number = 42;
    const clonedNumber = deepClone(number);
    expect(clonedNumber).toBe(number);
  });

  test('should return the same primitive value for strings', () => {
    const string = 'hello';
    const clonedString = deepClone(string);
    expect(clonedString).toBe(string);
  });

  test('should return the same primitive value for booleans', () => {
    const boolean = true;
    const clonedBoolean = deepClone(boolean);
    expect(clonedBoolean).toBe(boolean);
  });

  test('should return the same value for null', () => {
    const value = null;
    const clonedValue = deepClone(value);
    expect(clonedValue).toBe(value);
  });

  test('should return the same value for undefined', () => {
    const value = undefined;
    const clonedValue = deepClone(value);
    expect(clonedValue).toBe(value);
  });

  test('should deeply clone an array', () => {
    const array = [1, 2, { a: 3 }];
    const clonedArray = deepClone(array);
    expect(clonedArray).toEqual(array);
    expect(clonedArray).not.toBe(array);
    expect(clonedArray[2]).not.toBe(array[2]);
  });

  test('should deeply clone a plain object', () => {
    const obj = { a: 1, b: { c: 2 } };
    const clonedObj = deepClone(obj);
    expect(clonedObj).toEqual(obj);
    expect(clonedObj).not.toBe(obj);
    expect(clonedObj.b).not.toBe(obj.b);
  });

  test('should handle empty objects', () => {
    const obj = {};
    const clonedObj = deepClone(obj);
    expect(clonedObj).toEqual(obj);
    expect(clonedObj).not.toBe(obj);
  });

  test('should handle empty arrays', () => {
    const array = [];
    const clonedArray = deepClone(array);
    expect(clonedArray).toEqual(array);
    expect(clonedArray).not.toBe(array);
  });

  test('should handle nested arrays and objects', () => {
    const complexValue = { a: [1, { b: 2 }], c: { d: [3, 4] } };
    const clonedValue = deepClone(complexValue);
    expect(clonedValue).toEqual(complexValue);
    expect(clonedValue).not.toBe(complexValue);
    expect(clonedValue.a).not.toBe(complexValue.a);
    expect(clonedValue.a[1]).not.toBe(complexValue.a[1]);
    expect(clonedValue.c).not.toBe(complexValue.c);
    expect(clonedValue.c.d).not.toBe(complexValue.c.d);
  });
});

