    const result = mergeCause(error, CustomError);
    expect(result).toBe(error);
  });

  it.skip('should merge the cause if it is an instance of an error', () => {
    const cause = new Error('Cause error');
    const error = new Error('Test error');
    error.cause = cause;
    const result = mergeCause(error, CustomError);
    expect(result).toBe(error);
    expect(result.cause).toBeDefined();
    expect(result.cause.message).toBe(cause.message);
  });

  it.skip('should return a prefixed error if the cause is not an instance of ErrorClass', () => {
    const cause = new AnotherError('Another cause error');
    const error = new Error('Test error');
    error.cause = cause;
    const result = mergeCause(error, CustomError);
    expect(result).toBe(error);
    expect(result.cause).toBeDefined();
    expect(result.cause.message).toBe(cause.message);
  });

  it('should throw TypeError if error is not an object', () => {
    expect(() => mergeCause(null, CustomError)).toThrow(TypeError);
  });

  it.skip('should throw TypeError if ErrorClass is not a function', () => {
    const error = new Error('Test error');
    expect(() => mergeCause(error, null)).toThrow(TypeError);
  });

  it.skip('should handle errors with additional properties', () => {
    const cause = new Error('Cause error');
    const error = new Error('Test error');
    error.cause = cause;
    error.additionalInfo = 'Some info';
    const result = mergeCause(error, CustomError);
    expect(result).toBe(error);
    expect(result.cause).toBeDefined();
    expect(result.cause.message).toBe(cause.message);
    expect(result.additionalInfo).toBe('Some info');
  });

  it.skip('should not modify the original error properties unless necessary', () => {
    const cause = new Error('Cause error');
    const error = new Error('Test error');
    error.cause = cause;
    const originalMessage = error.message;
    const result = mergeCause(error, CustomError);
    expect(result.message).toBe(originalMessage);
  });
});

