    const oldOpt = { a: 1, b: 2 };
    const newOpt = { b: 3, c: 4 };
    isPlainObj.mockReturnValue(true);
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toEqual({ a: 1, b: 3, c: 4 });
    expect(result).not.toBe(oldOpt);
    expect(result).not.toBe(newOpt);
  });

  test.skip('should return newOpt if oldOpt is undefined and newOpt is a plain object', () => {
    const newOpt = { a: 1, b: 2 };
    isPlainObj.mockReturnValue(true);
    const result = mergeOpt(undefined, newOpt);
    expect(result).toEqual(newOpt);
  });

  test.skip('should return newOpt if oldOpt is undefined and newOpt is not a plain object', () => {
    const newOpt = [1, 2, 3];
    isPlainObj.mockReturnValueOnce(false);
    const result = mergeOpt(undefined, newOpt);
    expect(result).toBe(newOpt);
  });

  test.skip('should handle empty objects correctly', () => {
    const oldOpt = {};
    const newOpt = {};
    isPlainObj.mockReturnValue(true);
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).toEqual({});
  });

  test.skip('should not modify oldOpt or newOpt', () => {
    const oldOpt = { a: 1 };
    const newOpt = { b: 2 };
    isPlainObj.mockReturnValue(true);
    const result = mergeOpt(oldOpt, newOpt);
    expect(result).not.toBe(oldOpt);
    expect(result).not.toBe(newOpt);
    expect(oldOpt).toEqual({ a: 1 });
    expect(newOpt).toEqual({ b: 2 });
  });
});

