// test/subclass/validate/validateSubclass.test.js
const validateSubclass = require('../../../src/subclass/validate').validateSubclass;

describe('validateSubclass', () => {
  let classesData;

  beforeEach(() => {
    // Mocking the classesData set
    classesData = new Set();
    global.classesData = classesData;
  });

  afterEach(() => {
    // Clean up the global classesData
    delete global.classesData;
  });

  test.skip('should complete successfully when ErrorClass is in classesData', () => {
    class ValidError extends Error {}
    classesData.add(ValidError);

    expect(() => validateSubclass(ValidError)).not.toThrow();
  });

  test('should throw an error when ErrorClass is not in classesData', () => {
    class InvalidError extends Error {}

    expect(() => validateSubclass(InvalidError)).toThrow(
      `"new InvalidError()" must not be directly called.
This error class should be created like this instead:
  export const InvalidError = Error.subclass('InvalidError')`
    );
  });

  test.skip('should throw an error when ErrorClass is not a function', () => {
    const notAFunction = {};

    expect(() => validateSubclass(notAFunction)).toThrow(
      `"new Object()" must not be directly called.
This error class should be created like this instead:
  export const Object = Error.subclass('Object')`
    );
  });

  test('should not modify classesData set', () => {
    class AnotherValidError extends Error {}
    classesData.add(AnotherValidError);

    try {
      validateSubclass(AnotherValidError);
    } catch (e) {
      // Ignore error
    }

    expect(classesData.has(AnotherValidError)).toBe(true);
    expect(classesData.size).toBe(1);
  });

  test('should not modify ErrorClass or its prototype', () => {
    class UnchangedError extends Error {}
    classesData.add(UnchangedError);

    const originalPrototype = Object.getPrototypeOf(UnchangedError);

    try {
      validateSubclass(UnchangedError);
    } catch (e) {
      // Ignore error
    }

    expect(Object.getPrototypeOf(UnchangedError)).toBe(originalPrototype);
  });
});

test/merge/prefix/shouldPrefixCause.test.source:
const shouldPrefixCause = require('../../../src/merge/prefix').shouldPrefixCause;

describe('shouldPrefixCause', () => {
  class CustomError extends Error {}
  class AnotherError extends Error {}

  test('returns true when cause has a valid name matching ErrorClass', () => {
    const cause = new CustomError('Cause error');
    const error = new Error('Main error');
    error.cause = cause;
    expect(shouldPrefixCause(error, CustomError)).toBe(true);
  });

  test('returns true when cause has a name different from its constructor\'s name', () => {
    const cause = new Error('Cause error');
    cause.name = 'DifferentName';
    const error = new Error('Main error');
    error.cause = cause;
    expect(shouldPrefixCause(error, CustomError)).toBe(true);
  });

  test('returns false when cause has a name matching its constructor\'s name', () => {
    const cause = new Error('Cause error');
    const error = new Error('Main error');
    error.cause = cause;
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test.skip('returns false when cause is undefined', () => {
    const error = new Error('Main error');
    expect(shouldPrefixCause(error, CustomError)).toBe(false);
  });

  test('returns false when cause has no name', () => {
    const cause = new Error('Cause error');
    delete cause.name;
    const error = new Error('Main error');
    error.cause = cause;
    expect(shouldPrefixCause(error, CustomError)).toBe(false);
  });

  test.skip('returns false when cause is not an object', () => {
    const error = new Error('Main error');
    error.cause = null;
    expect(shouldPrefixCause(error, CustomError)).toBe(false);
  });

  test('throws TypeError when error is not an object', () => {
    expect(() => shouldPrefixCause(null, CustomError)).toThrow(TypeError);
  });

  test('throws TypeError when ErrorClass is not a function', () => {
    const cause = new CustomError('Cause error');
    const error = new Error('Main error');
    error.cause = cause;
    expect(() => shouldPrefixCause(error, null)).toThrow(TypeError);
  });
});

