    oldOpts = {
      pluginA: { option1: true, option2: false },
      pluginB: { option1: 'value1' },
    };
    newOpts = {
      pluginA: { option2: true, option3: 'new' },
      pluginB: { option1: 'newValue' },
    };
    name = 'pluginA';
  });

  test.skip('should return merged options for a valid plugin name', () => {
    const result = mergePluginOpts(oldOpts, newOpts, name);
    expect(result).toEqual([name, { option1: true, option2: true, option3: 'new' }]);
  });

  test.skip('should return undefined if plugin name does not exist in oldOpts', () => {
    name = 'pluginC';
    const result = mergePluginOpts(oldOpts, newOpts, name);
    expect(result).toBeUndefined();
  });

  test.skip('should return undefined if plugin name does not exist in newOpts', () => {
