// test/options/class/normalizeClassOpts.test.js
const { normalizeClassOpts } = require('../../../src/options/class');

describe('normalizeClassOpts', () => {
  class CustomError extends Error {
    constructor(message) {
      super(message);
      this.name = 'CustomError';
    }
  }

  it('should return the classOpts object if it is a plain object', () => {
    const classOpts = { key: 'value' };
    const result = normalizeClassOpts(CustomError, classOpts);
    expect(result).toBe(classOpts);
  });

  it('should return an empty object if classOpts is omitted', () => {
    const result = normalizeClassOpts(CustomError);
    expect(result).toEqual({});
  });

  it('should throw a TypeError if classOpts is not a plain object', () => {
    const invalidOpts = 'not an object';
    expect(() => normalizeClassOpts(CustomError, invalidOpts)).toThrow(TypeError);
  });

  it('should throw a TypeError with a descriptive message if classOpts is not a plain object', () => {
    const invalidOpts = 123;
    expect(() => normalizeClassOpts(CustomError, invalidOpts)).toThrow(
      new TypeError('The second argument of "CustomError.subclass()" must be a plain object, not: 123')
    );
  });

  it('should not modify the ParentError or classOpts objects', () => {
    const classOpts = { key: 'value' };
    const ParentError = CustomError;
    const result = normalizeClassOpts(ParentError, classOpts);
    expect(result).toBe(classOpts);
    expect(ParentError).toBe(CustomError);
  });

  it.skip('should throw a TypeError if ParentError is not a function', () => {
    const invalidParentError = 'not a function';
    expect(() => normalizeClassOpts(invalidParentError, {})).toThrow(TypeError);
  });
});

